package com.atskolla.teacher;
import android.graphics.*;import android.graphics.pdf.PdfDocument;import org.json.*;import java.io.*;import java.time.*;import java.util.*;import java.util.zip.*;import java.nio.charset.StandardCharsets;import static com.atskolla.teacher.Json.*;
final class ReportFiles {
 static int index(String status){return Arrays.asList("hadir","sakit","izin","alfa").indexOf(status);}
 static int[] counts(String id,List<JSONObject> logs){int[] count=new int[4];for(JSONObject log:logs)if(s(log,"student_id").equals(id)){int i=index(s(log,"status"));if(i>=0)count[i]++;}return count;}
 static Map<String,String> cells(List<JSONObject> logs){Map<String,String> result=new HashMap<>();for(JSONObject l:logs){String status=s(l,"status");result.put(s(l,"student_id")+":"+s(l,"date"),status.equals("hadir")?"H":status.equals("sakit")?"S":status.equals("izin")?"I":status.equals("alfa")?"A":"");}return result;}
 static byte[] pdf(String school,String teacher,String title,String from,String to,List<JSONObject> pupils,List<JSONObject> logs)throws Exception{
  PdfDocument doc=new PdfDocument();Paint p=new Paint(3);Map<String,String> cells=cells(logs);LocalDate start=LocalDate.parse(from),end=LocalDate.parse(to);int pageNo=0;boolean departure=title.toLowerCase(Locale.ROOT).contains("pulang");
  try{for(LocalDate month=start.withDayOfMonth(1);!month.isAfter(end);month=month.plusMonths(1)){LocalDate first=month.isBefore(start)?start:month,last=month.withDayOfMonth(month.lengthOfMonth()).isAfter(end)?end:month.withDayOfMonth(month.lengthOfMonth());int days=(int)java.time.temporal.ChronoUnit.DAYS.between(first,last)+1;for(int offset=0;offset<Math.max(1,pupils.size());offset+=22){PdfDocument.Page page=doc.startPage(new PdfDocument.PageInfo.Builder(842,595,++pageNo).create());Canvas c=page.getCanvas();p.setColor(Color.WHITE);c.drawPaint(p);draw(c,p,school,28,32,16,true,Ui.INK);draw(c,p,title,28,55,12,true,Ui.BLUE);draw(c,p,date(first.toString())+" – "+date(last.toString()),28,74,9,false,Ui.MUTED);float cell=Math.min(18,490f/days),left=244,rowY=100;p.setColor(0xFF5B6CF9);c.drawRect(28,86,814,112,p);draw(c,p,"NO / NIS / NAMA SISWA",34,102,8,true,Color.WHITE);for(int d=0;d<days;d++)draw(c,p,String.valueOf(first.plusDays(d).getDayOfMonth()),left+d*cell+3,102,7,true,Color.WHITE);for(int k=0;k<(departure?1:4);k++)draw(c,p,departure?"V":new String[]{"H","S","I","A"}[k],737+k*19,102,7,true,Color.WHITE);
    for(int i=offset;i<Math.min(offset+22,pupils.size());i++){JSONObject pupil=pupils.get(i);float y=112+(i-offset)*17;if((i-offset)%2==0){p.setColor(0xFFF0F2FC);c.drawRect(28,y,814,y+17,p);}String label=(i+1)+". "+s(pupil,"student_id")+"  "+s(pupil,"name");if(label.length()>42)label=label.substring(0,40)+"…";draw(c,p,label,33,y+11,7,false,Ui.INK);for(int d=0;d<days;d++){String value=cells.getOrDefault(s(pupil,"id")+":"+first.plusDays(d),"");if(departure&&value.equals("H"))value="V";int tint=value.equals("H")||value.equals("V")?0xFF079B76:value.equals("A")?0xFFDF4051:Ui.BLUE;draw(c,p,value,left+d*cell+4,y+11,7,true,tint);}List<JSONObject> monthLogs=new ArrayList<>();for(JSONObject log:logs)if(s(log,"date").compareTo(first.toString())>=0&&s(log,"date").compareTo(last.toString())<=0)monthLogs.add(log);int[] totals=counts(s(pupil,"id"),monthLogs);for(int k=0;k<(departure?1:4);k++)draw(c,p,String.valueOf(totals[k]),737+k*19,y+11,7,true,Ui.BLUE);}
    draw(c,p,departure?"V: Tercatat pulang":"H: Hadir   S: Sakit   I: Izin   A: Alfa",28,510,8,false,Ui.MUTED);draw(c,p,"Guru: "+teacher,28,532,9,true,Ui.INK);draw(c,p,"ATSkolla • Halaman "+pageNo,687,566,8,false,Ui.MUTED);doc.finishPage(page);
   }}ByteArrayOutputStream out=new ByteArrayOutputStream();doc.writeTo(out);return out.toByteArray();}finally{doc.close();}
 }
 static void draw(Canvas c,Paint p,String text,float x,float y,int size,boolean bold,int color){p.setColor(color);p.setTextSize(size);p.setTypeface(Typeface.create("sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));c.drawText(text,x,y,p);}
 static String xml(String value){return value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replaceAll("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]","");}
 static void entry(ZipOutputStream zip,String name,String content)throws IOException{zip.putNextEntry(new ZipEntry(name));zip.write(content.getBytes(StandardCharsets.UTF_8));zip.closeEntry();}
 static byte[] xlsx(String school,String title,String from,String to,List<JSONObject> pupils,List<JSONObject> logs)throws Exception{
  boolean departure=title.toLowerCase(Locale.ROOT).contains("pulang");ByteArrayOutputStream out=new ByteArrayOutputStream();Map<String,String> values=cells(logs);List<List<String>> rows=new ArrayList<>();rows.add(Arrays.asList(school));rows.add(Arrays.asList(title));rows.add(Arrays.asList(date(from)+" – "+date(to)));List<String> header=new ArrayList<>(Arrays.asList("No","NIS","Nama"));LocalDate start=LocalDate.parse(from),end=LocalDate.parse(to);for(LocalDate day=start;!day.isAfter(end);day=day.plusDays(1))header.add(day.toString());header.addAll(departure?Collections.singletonList("V"):Arrays.asList("H","S","I","A"));rows.add(header);int no=0;
  for(JSONObject pupil:pupils){List<String> row=new ArrayList<>(Arrays.asList(String.valueOf(++no),s(pupil,"student_id"),s(pupil,"name")));for(LocalDate day=start;!day.isAfter(end);day=day.plusDays(1)){String value=values.getOrDefault(s(pupil,"id")+":"+day,"");row.add(departure&&value.equals("H")?"V":value);}int[] sums=counts(s(pupil,"id"),logs);for(int k=0;k<(departure?1:4);k++)row.add(String.valueOf(sums[k]));rows.add(row);}
  StringBuilder sheet=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetViews><sheetView workbookViewId=\"0\"><pane ySplit=\"4\" xSplit=\"3\" topLeftCell=\"D5\" activePane=\"bottomRight\" state=\"frozen\"/></sheetView></sheetViews><cols><col min=\"1\" max=\"1\" width=\"6\" customWidth=\"1\"/><col min=\"2\" max=\"2\" width=\"20\" customWidth=\"1\"/><col min=\"3\" max=\"3\" width=\"30\" customWidth=\"1\"/><col min=\"4\" max=\"400\" width=\"12\" customWidth=\"1\"/></cols><sheetData>");int rn=0;for(List<String> row:rows){sheet.append("<row r=\"").append(++rn).append("\">");int col=0;for(String value:row){col++;boolean numeric=rn>4&&(col==1||col>header.size()-(departure?1:4))&&value.matches("[0-9]+");sheet.append("<c r=\"").append(column(col)).append(rn).append("\"");if(numeric)sheet.append("><v>").append(value).append("</v></c>");else sheet.append(" t=\"inlineStr\"><is><t xml:space=\"preserve\">").append(xml(value)).append("</t></is></c>");}sheet.append("</row>");}sheet.append("</sheetData></worksheet>");
  try(ZipOutputStream zip=new ZipOutputStream(out)){entry(zip,"[Content_Types].xml","<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/></Types>");entry(zip,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");entry(zip,"xl/workbook.xml","<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Rekap Kehadiran\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>");entry(zip,"xl/_rels/workbook.xml.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/></Relationships>");entry(zip,"xl/worksheets/sheet1.xml",sheet.toString());}return out.toByteArray();
 }
 static String column(int number){StringBuilder c=new StringBuilder();while(number>0){number--;c.insert(0,(char)('A'+number%26));number/=26;}return c.toString();}
}
